const cols="ABCDEFGHJ";
function ns(p){const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);}
function group(b,p){const c=b[p],seen=new Set([p]),stack=[p],lib=new Set();while(stack.length){const q=stack.pop();for(const n of ns(q)){if(b[n]===c&&!seen.has(n)){seen.add(n);stack.push(n);}else if(b[n]===".")lib.add(n);}}return {stones:[...seen],liberties:[...lib]};}
function parse(r){const s=r.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");const b={};for(const line of s.split("\\n")){const m=line.match(/^\\s*([1-9])\\s+([.XO](?:\\s+[.XO]){8})\\s+[1-9]\\s*$/);if(m)m[2].split(/\\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}return {s,b};}
const log=load("log41"),b={};for(let y=1;y<=9;y++)for(const c of cols)b[c+y]=".";
const captures={X:0,O:0},events=[],moves=[],checks=[];
const selection=parse(log.selection);if(Object.keys(b).some(p=>b[p]!==selection.b[p]))throw Error("selection mismatch");
checks.push({moveNumber:0,board:true,captures:true});
function actualMove(color,move){const num=moves.length+1;moves.push({number:num,color:color==="X"?"B":"W",move});if(move==="pass")return;if(b[move]!==".")throw Error("occupied historical move "+num);b[move]=color;let removed=[];for(const n of ns(move)){if(b[n]!=="."&&b[n]!==color){const g=group(b,n);if(!g.liberties.length){for(const q of g.stones){b[q]=".";removed.push(q);}}}}if(!group(b,move).liberties.length)throw Error("suicide history "+num);captures[color]+=removed.length;if(removed.length)events.push({number:num,color,move,captured:removed.sort()});}
for(const response of log.responses){const {s,b:returned}=parse(response.response);const opp=s.match(/Your opponent played ([A-HJ][1-9])\\./);const oppmove=opp?opp[1]:s.includes("Your opponent passed.")?"pass":null;if(!oppmove)throw Error("reply missing");actualMove("X",response.move);actualMove("O",oppmove);if(Object.keys(b).some(p=>b[p]!==returned[p]))throw Error("board mismatch at "+moves.length);const counts=s.match(/Captured by Black: (\\d+); by White: (\\d+)/);if(!counts||captures.X!==+counts[1]||captures.O!==+counts[2])throw Error("capture mismatch");checks.push({moveNumber:moves.length,board:true,captures:true});}
const scoring={...b};for(const p of ["D8","E8"])scoring[p]=".";
let seen=new Set(),area={X:0,O:0,neutral:0},territories=[],rows=[];
for(const p of Object.keys(scoring)){if(scoring[p]!=="."){area[scoring[p]]++;continue;}if(seen.has(p))continue;const stack=[p],points=[],border=new Set();seen.add(p);while(stack.length){const q=stack.pop();points.push(q);for(const n of ns(q)){if(scoring[n]==="."&&!seen.has(n)){seen.add(n);stack.push(n);}else if(scoring[n]!==".")border.add(scoring[n]);}}const owner=border.size===1?[...border][0]:"neutral";area[owner]+=points.length;territories.push({owner,points:points.sort()});}
for(let y=1;y<=9;y++){let X=0,O=0;for(const c of cols){const p=c+y;let owner=scoring[p];if(owner===".")owner=territories.find(r=>r.points.includes(p)).owner;if(owner==="X")X++;if(owner==="O")O++;}rows.push({row:y,Black:X,White:O});}
log.actualMoves=moves;log.captureEvents=events;log.verification={checks,returnedBoards:checks.length,allMatched:true};log.finalArea={Black:area.X,White:area.O,komi:7,neutral:area.neutral,removedDead:["D8","E8"],territories,rows,displayedStones:{Black:Object.values(b).filter(v=>v==="X").length,White:Object.values(b).filter(v=>v==="O").length},result:"W+4"};
store("log41",log);store("sgf41","(;GM[1]FF[4]CA[UTF-8]SZ[9]RU[Chinese]KM[7]PB[Codex]PW[KataGo human-style 20k]DT[2026-10-06]RE[W+4]"+moves.map(m=>";"+m.color+"["+(m.move==="pass"?"":String.fromCharCode(97+cols.indexOf(m.move[0]))+String.fromCharCode(97+9-Number(m.move[1])))+"]").join("")+")\\n");
text({moves,events,verification:log.verification,area:log.finalArea});
`);
await eval("(async()=>{"+load("verify41src")+"})()");
await eval("(async()=>{"+load("helper41")+"\nawait save();})()");
text(await tools.apply_patch("*** Begin Patch\n*** Add File: game-041.sgf\n+"+load("sgf41").trimEnd()+"\n*** Add File: game-041-verification.js\n"+load("verify41src").trim().split("\n").map(x=>"+"+x).join("\n")+"\n*** End Patch"));

